from typing import TypedDict, List, Any

from dataclasses import dataclass
from pathlib import Path
import io

from rdflib import Graph, URIRef, Literal
from rdflib.namespace import RDF, SDO, RDFS
from pyvis.network import Network


URL_PREFIX = "http://mygames.xyz/"
OUT_PATH = Path("./out/")


@dataclass
class Game:
    name: str
    genre: str
    rating: int  # 0-100
    platforms: List[str]
    developer: str

    @staticmethod
    def _make_triples_for_property(
        game: URIRef,
        game_property: str,
        game_property_category: str,
        entity_class: URIRef,
        relationship: URIRef,
    ) -> List[tuple[URIRef, URIRef, Literal]]:
        triples = []

        entity = URIRef(
            f"{URL_PREFIX}{game_property_category}/{game_property.lower().replace(" ", "-").replace("/", "-")}"
        )
        triples.append((entity, RDF.type, entity_class))
        triples.append((entity, SDO.name, Literal(game_property)))
        triples.append((game, relationship, entity))

        return triples

    # TODO: make separate make_triple_for_field private method
    def build_triples(self) -> List[tuple[URIRef, URIRef, Literal]]:
        triples = []
        game = URIRef(URL_PREFIX + "games/" + self.name.lower().replace(" ", "-"))
        triples.append((game, RDF.type, SDO.VideoGame))
        triples.append((game, SDO.name, Literal(self.name)))

        triples += self._make_triples_for_property(
            game, self.genre, "genres", SDO.DefinedTerm, SDO.genre
        )

        for platform_name in self.platforms:
            triples += self._make_triples_for_property(
                game, platform_name, "platforms", SDO.Thing, SDO.gamePlatform
            )

        triples += self._make_triples_for_property(
            game, self.developer, "developers", SDO.Organization, SDO.author
        )

        rating = URIRef(URL_PREFIX + "ratings/" + self.name.lower().replace(" ", "-"))
        triples.append((rating, RDF.type, SDO.Rating))
        triples.append((rating, SDO.ratingValue, Literal(self.rating)))
        triples.append((game, SDO.reviewRating, rating))

        return triples


def add_triples(graph: Graph, triples: List[tuple[URIRef, Any, Literal]]) -> None:
    for triple in triples:
        graph.add(triple)


def get_short_label(element, graph):
    """
    Перетворює довгий URI на короткий рядок (наприклад, 'ex:John' або 'schema:Person').
    Якщо це літерал, повертає його значення.
    """
    if isinstance(element, Literal):
        return f'"{element}"'

    if isinstance(element, URIRef):
        # Намагаємося скоротити за допомогою відомих графу префіксів
        try:
            return graph.namespace_manager.normalizeUri(element)
        except Exception:
            # Якщо не вдалося, беремо слово після останнього '/' або '#'
            return element.split("/")[-1].split("#")[-1]

    return str(element)


def get_node_style(node_uri, graph):
    if isinstance(node_uri, Literal):
        return {"color": "#b8e994", "shape": "box"}  # Світло-зелений квадрат

    if (node_uri, RDF.type, RDFS.Class) in graph or node_uri.endswith("Class"):
        return {"color": "#fad390", "shape": "ellipse"}  # Жовтий/Пастельний

    # other instance
    return {"color": "#81ecec", "shape": "dot"}  # Блакитний круг


def visualize_graph(rdf_graph, output_filename=OUT_PATH / "rdf_graph.html"):
    net = Network(
        directed=True,
        height="800px",
        width="100%",
        bgcolor="#f8f9fa",
        font_color="#2d3436",
    )

    net.barnes_hut(gravity=-2000, central_gravity=0.3, spring_length=150)

    net.show_buttons(filter_=["physics"])

    for subj, pred, obj in rdf_graph:
        s_label = get_short_label(subj, rdf_graph)
        o_label = get_short_label(obj, rdf_graph)
        p_label = get_short_label(pred, rdf_graph)

        s_style = get_node_style(subj, rdf_graph)
        o_style = get_node_style(obj, rdf_graph)

        net.add_node(
            s_label,
            label=s_label,
            title=str(subj),
            color=s_style["color"],
            shape=s_style["shape"],
        )
        net.add_node(
            o_label,
            label=o_label,
            title=str(obj),
            color=o_style["color"],
            shape=o_style["shape"],
        )

        net.add_edge(
            s_label, o_label, label=p_label, color="#b2bec3", arrowStrikethrough=False
        )

    net.show(str(output_filename), notebook=False)


def save_graph_to_file(graph: Graph, filepath: Path, out_format: str) -> None:
    with open(filepath, "w") as graph_out:
        graph_out.write(graph.serialize(format=out_format))


def load_graph_from_file(filepath: Path) -> Graph:
    g = Graph()
    with open(filepath) as graph_in:
        graph.parse(filepath)

    return graph


def modify_turtle_file(filepath: Path) -> None:
    another_game = """
<http://mygames.xyz/games/doom> a schema:VideoGame ;
    schema:author <http://mygames.xyz/developers/id-software> ;
    schema:gamePlatform <http://mygames.xyz/platforms/pc>,
        <http://mygames.xyz/platforms/dos> ;
    schema:genre <http://mygames.xyz/genres/shooter> ;
    schema:name "Doom" ;
    schema:reviewRating <http://mygames.xyz/ratings/doom> .

<http://mygames.xyz/developers/id-software> a schema:Organization ;
    schema:name "id Software" .

<http://mygames.xyz/genres/shooter> a schema:DefinedTerm ;
    schema:name "shooter" .

<http://mygames.xyz/ratings/doom> a schema:Rating ;
    schema:ratingValue 82 .

<http://mygames.xyz/platforms/dos> a schema:Thing ;
    schema:name "DOS" .
    """
    with open(filepath, "a") as turtle_file:
        turtle_file.write(another_game)


